INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Software > Auswahl > Anwendungen > Office-Programme
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Office-Programme unabhängig von den Hardwareanforderungen ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Hardware muss Systemvoraussetzungen erfüllen"}, {"text": "Ja", "correct": false, "because": "Inkompatibilität beeinträchtigt Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl von Office-Programmen immer die Bedürfnisse der Nutzer berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nutzeranforderungen bestimmen Funktionalität"}, {"text": "Nein", "correct": false, "because": "Bedürfnisse sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Office-Programme immer als Cloud-Lösung verfügbar?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokale Installationen möglich"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich Cloud"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Office-Programme ohne Rücksicht auf Lizenzmodelle ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Lizenzen beeinflussen Kosten und Nutzung"}, {"text": "Ja", "correct": false, "because": "Lizenzierung ist relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind alle Office-Programme plattformunabhängig?', 2, '[{"text": "Nein", "correct": true, "because": "Manche sind betriebssystemabhängig"}, {"text": "Ja", "correct": false, "because": "Plattformabhängigkeit existiert"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auswahl von Office-Programmen am wichtigsten?', 3, '[{"text": "Nutzungsanforderungen", "correct": true, "because": "Bestimmen benötigte Funktionen"}, {"text": "Kosten", "correct": false, "because": "Wichtig, aber sekundär"}, {"text": "Marke", "correct": false, "because": "Weniger entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Office-Programm wird am häufigsten für Tabellenkalkulation verwendet?', 2, '[{"text": "Microsoft Excel", "correct": true, "because": "Marktführer in Tabellenkalkulation"}, {"text": "Microsoft Word", "correct": false, "because": "Textverarbeitung"}, {"text": "Microsoft PowerPoint", "correct": false, "because": "Präsentationen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Lizenzform ist typisch für moderne Office-Programme?', 2, '[{"text": "Abonnement", "correct": true, "because": "Cloud-Modelle wie Microsoft 365 üblich"}, {"text": "Einmalkauf", "correct": false, "because": "Weniger verbreitet"}, {"text": "Open Source", "correct": false, "because": "Seltener bei Marktführern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion ist für Textverarbeitung in Office-Programmen entscheidend?', 3, '[{"text": "Formatierung", "correct": true, "because": "Kernfunktion für Dokumente"}, {"text": "Datenbankverwaltung", "correct": false, "because": "Andere Programme"}, {"text": "Grafikdesign", "correct": false, "because": "Spezialisierte Software"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil von Cloud-basierten Office-Programmen?', 2, '[{"text": "Zugang von überall", "correct": true, "because": "Flexibilität durch Internet"}, {"text": "Geringere Kosten", "correct": false, "because": "Abo oft teurer"}, {"text": "Schnellere Installation", "correct": false, "because": "Nicht primär"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte beeinflussen die Auswahl von Office-Programmen?', 4, '[{"text": "Nutzeranforderungen", "correct": true, "because": "Definiert Funktionalität"}, {"text": "Hardwarekompatibilität", "correct": true, "because": "Muss System unterstützen"}, {"text": "Lizenzkosten", "correct": true, "because": "Beeinflusst Budget"}, {"text": "Farbe der Benutzeroberfläche", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bieten Office-Programme typischerweise?', 3, '[{"text": "Textverarbeitung", "correct": true, "because": "Grundfunktion"}, {"text": "Tabellenkalkulation", "correct": true, "because": "Für Datenanalyse"}, {"text": "Präsentationserstellung", "correct": true, "because": "Für Vorträge"}, {"text": "3D-Modellierung", "correct": false, "because": "Spezialisierte Software"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Office-Programme?', 3, '[{"text": "Benutzerfreundlichkeit", "correct": true, "because": "Intuitive Bedienung"}, {"text": "Breite Kompatibilität", "correct": true, "because": "Dateien weit verbreitet"}, {"text": "Kollaborationsfunktionen", "correct": true, "because": "Teamarbeit möglich"}, {"text": "Geringer Speicherbedarf", "correct": false, "because": "Kann hoch sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Auswahl von Office-Programmen auftreten?', 4, '[{"text": "Hohe Lizenzkosten", "correct": true, "because": "Abo-Modelle teuer"}, {"text": "Inkompatibilität mit Hardware", "correct": true, "because": "Alte Systeme ungeeignet"}, {"text": "Fehlende Funktionen", "correct": true, "because": "Nicht alle Bedürfnisse gedeckt"}, {"text": "Langsame Installation", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Office-Programme sind marktführend?', 3, '[{"text": "Microsoft Word", "correct": true, "because": "Textverarbeitung"}, {"text": "Microsoft Excel", "correct": true, "because": "Tabellenkalkulation"}, {"text": "Microsoft PowerPoint", "correct": true, "because": "Präsentationen"}, {"text": "Adobe Photoshop", "correct": false, "because": "Grafikdesign"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Office-Programme erfordern kompatible Hardware. b) Sie sind immer kostenlos verfügbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ja, kostenlos nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Microsoft Excel ist für Tabellenkalkulation geeignet. b) Office-Programme sind immer Cloud-basiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Excel ja, Cloud optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Office-Programme unterstützen Kollaboration. b) Lizenzkosten sind bei der Auswahl irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kollaboration ja, Kosten relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Microsoft Word ist ein Textverarbeitungsprogramm. b) Alle Office-Programme sind plattformunabhängig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Word ja, Plattformabhängigkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Cloud-basierte Office-Programme ermöglichen flexiblen Zugriff. b) Hardwareanforderungen sind bei der Auswahl unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Cloud ja, Hardware wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

